import{_ as d,o as r,c as a,ag as e}from"./chunks/framework.D45daZFh.js";const g=JSON.parse('{"title":"成人高血压食养指南（2023年版）","description":"国家卫健委《成人高血压食养指南（2023年版）》可执行整理：每日盐 5g 以内怎么落地的行动清单，每条注明原文出处。","frontmatter":{"title":"成人高血压食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","document_no":"国卫办食品函〔2023〕5号","source_url":"https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml","pdf_url":"https://www.chinacdc.cn/jkyj/yyyjk2/jswj13949/202504/P020250407389243687542.pdf","status":"现行","tags":["高血压","食养","限盐","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人高血压食养指南（2023年版）》可执行整理：每日盐 5g 以内怎么落地的行动清单，每条注明原文出处。"},"headers":[],"relativePath":"guides/hypertension-2023.md","filePath":"guides/hypertension-2023.md"}'),o={name:"guides/hypertension-2023.md"};function h(n,t,s,l,i,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="成人高血压食养指南-2023年版" tabindex="-1">成人高血压食养指南（2023年版） <a class="header-anchor" href="#成人高血压食养指南-2023年版" aria-label="Permalink to &quot;成人高血压食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文、逐条标注出处章节</strong>，可在原文中找到对应内容；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">通知页</a> · <a href="https://www.chinacdc.cn/jkyj/yyyjk2/jswj13949/202504/P020250407389243687542.pdf" target="_blank" rel="noreferrer">全文 PDF</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人高血压患者，以及血压偏高、有高血压家族史或生活方式风险较高的人群及其家人；基层卫生工作者与营养指导人员亦可参考（原文·前言）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>五条原则</strong>：减钠增钾、饮食清淡 → 合理膳食、科学食养 → 吃动平衡、健康体重 → 戒烟限酒、心理平衡 → 监测血压、自我管理。（三·开篇）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>食盐</td><td>逐步降至 <strong>5g 以下</strong>（钠 ≤2000mg）</td><td>三(一)、附录1(九)</td></tr><tr><td>蔬菜</td><td><strong>≥300g</strong>，至少 3 种、最好 5 种以上，深色蔬菜占一半以上</td><td>附录1(四)</td></tr><tr><td>水果</td><td><strong>200～350g</strong>，至少 1 种、最好 2 种以上</td><td>附录1(四)</td></tr><tr><td>鱼、禽、蛋、瘦肉合计</td><td><strong>120～200g</strong></td><td>附录1(二)</td></tr><tr><td>奶制品</td><td>相当于 <strong>300ml 以上</strong>液态奶</td><td>附录1(二)</td></tr><tr><td>大豆及制品</td><td><strong>15～25g</strong>（≈豆浆 220～360g 或南豆腐 84～140g）</td><td>附录1(三)</td></tr><tr><td>坚果（原味）</td><td><strong>每周 50～70g</strong></td><td>附录1(五)</td></tr><tr><td>烹调油</td><td><strong>25～30g</strong>，几种植物油交替</td><td>附录1(六)</td></tr><tr><td>白水</td><td><strong>1500～1700ml</strong>（温和气候、轻活动水平）</td><td>附录1(八)</td></tr><tr><td>全谷物或杂豆</td><td>占谷类 <strong>1/4～1/2</strong></td><td>三(二)1</td></tr><tr><td>体重</td><td>BMI <strong>18.5～23.9</strong>；腰围男 <strong>&lt;85cm</strong>、女 <strong>&lt;80cm</strong></td><td>三(三)</td></tr><tr><td>运动</td><td><strong>每周 4～7 天、每天累计 30～60 分钟</strong>中等强度</td><td>三(三)</td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>富钾蔬菜优先买：菠菜、芥兰、莴笋叶、空心菜、苋菜、口蘑</td><td>附录1(四)</td></tr><tr><td>肾功能良好者可选用高钾低钠盐（肾功能不全者补钾前先问医生）</td><td>三(一)</td></tr><tr><td>少买或不买咸味面包、方便面、挂面等加钠谷类制品</td><td>附录1(一)</td></tr><tr><td>少买培根、香肠、腊肠等加工红肉制品，少吃油炸食品和动物内脏</td><td>三(一)</td></tr><tr><td>不买含糖饮料；买原味坚果（非调味坚果）</td><td>附录1(五)(八)</td></tr><tr><td>【本站提示】预包装食品看营养成分表&quot;钠&quot;一栏，NRV% 越高含钠越高——原文指出加工食品已是重要钠盐摄入途径</td><td>三(一)</td></tr></tbody></table><h3 id="🍳-做" tabindex="-1">🍳 做 <a class="header-anchor" href="#🍳-做" aria-label="Permalink to &quot;🍳 做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>主食粗细搭配：全谷物或杂豆占到谷类的 1/4～1/2</td><td>三(二)1</td></tr><tr><td>食用油选菜籽油、亚麻籽油、橄榄油、葵花籽油、玉米油等富含不饱和脂肪酸的油，几种交替使用；避免油炸和含反式脂肪的食品</td><td>附录1(六)</td></tr><tr><td>少用酱油、酱类、蚝油、鸡精、味精等含钠调味品</td><td>三(二)1、附录1(九)</td></tr><tr><td>【本站提示】用限盐勺把&quot;每日 5g&quot;变成可操作的量：全家按人数分配全天总盐量，含调味品折算</td><td>三(一)</td></tr></tbody></table><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么吃</th><th>出处</th></tr></thead><tbody><tr><td>每日食盐逐步降到 5g 以下；清淡饮食，少吃高脂肪、高胆固醇食物</td><td>三(一)</td></tr><tr><td>蔬果充足且<strong>不能相互替代</strong>；深色蔬菜过半</td><td>三(二)1、附录1(四)</td></tr><tr><td>蛋白质多选奶类、鱼类、大豆及其制品；限制添加糖</td><td>三(二)1</td></tr><tr><td>豆豉、豆瓣酱、腐乳等少吃</td><td>附录1(三)</td></tr><tr><td>不饮或限制饮酒——即使少量饮酒也对健康有不良影响，饮酒者尽量戒酒</td><td>三(四)、附录1(七)</td></tr><tr><td>不喝浓茶和浓咖啡，不吃特别辛辣刺激的食物</td><td>附录1(十)</td></tr><tr><td>按中医证型调整口味：肝火上炎清淡平肝 / 痰湿内阻清淡易消化少食多餐 / 瘀血内阻清淡温平 / 阴虚阳亢清淡养阴生津 / 肾精不足偏温补 / 气血两虚少食多餐细软滋补 / 冲任失调清淡富营养</td><td>三(二)2</td></tr></tbody></table><h3 id="🏃-动" tabindex="-1">🏃 动 <a class="header-anchor" href="#🏃-动" aria-label="Permalink to &quot;🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么动</th><th>出处</th></tr></thead><tbody><tr><td>除日常活动外，每周 4～7 天、每天累计 30～60 分钟中等强度身体活动</td><td>三(三)</td></tr><tr><td>或每周累计 2.5～5 小时中等强度 / 1.25～2.5 小时高强度有氧运动；减少静态行为时间</td><td>三(三)</td></tr><tr><td>超重肥胖者减重：每日能量比原来减少 300～500kcal，控制高脂肪食物、含糖饮料和酒类；参考：18～49 岁轻活动水平能量需要约男 2250kcal、女 1800kcal</td><td>三(三)</td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>定期监测血压、了解达标状态，遵医嘱长期治疗与自我管理；随诊安排参考附录5 的血压水平分级</td><td>三(五)</td></tr><tr><td><strong>不建议</strong>服用钾补充剂（包括药物）来降血压；肾功能不全者补钾前咨询医生</td><td>三(一)</td></tr><tr><td>精神压力大、血压波动时，可到专业医疗机构就诊进行压力管理；规律作息、不熬夜</td><td>三(四)</td></tr><tr><td>参考三种膳食模式选择适合自己的：得舒饮食（DASH）/ 东方健康膳食模式 / 中国心脏健康膳食（CHH-Diet）</td><td>三(五)后</td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;水果能代替蔬菜&quot;</td><td>蔬菜和水果<strong>不能相互替代</strong></td><td>三(二)1</td></tr><tr><td>&quot;少量喝酒没关系&quot;</td><td>即使少量饮酒也会对健康造成不良影响</td><td>三(四)</td></tr><tr><td>&quot;吃点钾片补钾降压&quot;</td><td>不建议服用钾补充剂（包括药物）来降低血压</td><td>三(一)</td></tr><tr><td>&quot;面包挂面不咸，不用控钠&quot;</td><td>少食用或不食用咸味面包、方便面、挂面等加钠谷类制品</td><td>附录1(一)</td></tr></tbody></table><h2 id="分地区食谱怎么用" tabindex="-1">分地区食谱怎么用 <a class="header-anchor" href="#分地区食谱怎么用" aria-label="Permalink to &quot;分地区食谱怎么用&quot;">​</a></h2><ul><li>**附录3《不同地区食谱示例》**覆盖东北、西北、华北、华东、华中、西南、华南七大地区，每区按不同季节给出食谱套餐——先翻到自己所在地区，再对应当下季节参考。</li><li>**附录2《常见食物交换表》**给了 7 类食物的换算量：不想照搬食谱时，可用交换表把同类食物等量替换。</li><li>**附录4《不同证型食养方举例》**按七个证型各给 2 个食养方（如肝火上炎证的芹菜粳米瘦肉粥、枸杞菊花决明饮）；原文备注：食药物质应在限定使用范围和剂量内使用，食用方法请咨询医师、营养指导人员等专业人员。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2023〕5号（待人工复核）</td></tr><tr><td>全文 PDF</td><td><a href="https://www.chinacdc.cn/jkyj/yyyjk2/jswj13949/202504/P020250407389243687542.pdf" target="_blank" rel="noreferrer">疾控中心营养与健康所收录直链</a></td></tr></tbody></table>',26)])])}const u=d(o,[["render",h]]);export{g as __pageData,u as default};
